// captured dimensions (aspect for inline + viewer)
//--- Read PNG bytes -> base64 for the request
int
ph =
FileOpen
(AI_IMG_DIR + base +
".png"
,
FILE_READ
|
FILE_BIN
);
if
(ph !=
INVALID_HANDLE
)
     {
uchar
bytes[];
int
sz = (
int
)
FileReadArray
(ph, bytes,
0
