Reached from that footer action, we define the "Ai_AttachChartScreenshot" function to clear any earlier staged shot, capture a fresh one, and hold its base name, dimensions, and base64 in the attachment globals until we send. For the opposite case, we add the "Ai_RemoveAttachment" function, where we delete the staged files and reset the same state when we drop the attachment before sending. Either way, we are only holding the image, so we finish by folding it into the message content the model actually receives.
Building the Multimodal Content
To let the model see, the message stops being a plain string and becomes a content array holding both the text and the encoded image.
string
Ai12_BuildVisionContent(
const
string
escapedText,
const
string
b64)
  {
const
string
detail =
"high"
;
// deliberately-attached chart: read it closely
string
content =
"["
;
   content +=
"{\"type\":\"text\",\"text\":\""
+ escapedText +
"\"},"
;
   content +=
"{\"type\":\"image_url\",\"image_url\":{\"url\":\"data:image/png;base64,"
+ b64 +
"\",\"detail\":\""
+ detail +
"\"}}"
;
   content +=
"]"
;
return
content;
  }
Given the escaped prompt text and the base64 image, we define the "Ai12_BuildVisionContent" function to wrap the two into a content array, where we tag the image as a base64 data URL and ask for a high-detail read since we attached it deliberately. We rely on this payload to turn a plain message into one the model can see, and we reach for it in the send path whenever a shot is staged. The image now travels to the model, but we still need it on screen, so from here we decode it back into pixels and draw it as a thumbnail and a full viewer.
Decoding the Stored Image
To show a saved screenshot back in the panel, we read the BMP copy off disk and turn it into the ARGB pixels the canvas draws with.
int
Ai_LE32(
const
uchar
&b[],
int
p)
  {
return
(
int
)b[p] | ((
int
)b[p+
1
] <<
8
) | ((
int
)b[p+
2
] <<
16
) | ((
int
)b[p+
3
] <<
24
);
  }
bool
Ai_DecodeBMP(
string
file,
uint
&px[],
int
&w,
int
&h)
  {
int
fh =
FileOpen
(file,
FILE_READ
|
FILE_BIN
);
if
(fh ==
INVALID_HANDLE
)
return
false
;
uchar
b[];
int
sz = (
int
)
FileReadArray
(fh, b,
0
,
WHOLE_ARRAY
);
FileClose
(fh);
if
(sz <
54
|| b[
0
] !=
'B'
|| b[
1
] !=
'M'
)
return
false
;
int
dataOff = Ai_LE32(b,
10
);
int
bw      = Ai_LE32(b,
18
);
int
bhRaw   = Ai_LE32(b,
22
);
int
bpp     = (
int
)b[
28
] | ((
int
)b[
29
] <<
8
);
bool
topDown = (bhRaw <
0
);
int
bh = topDown ? -bhRaw : bhRaw;
if
(bw <=
0
|| bh <=
0
|| (bpp !=
24
&& bpp !=
32
))
return
false
;
int
bpx     = bpp /
8
;
int
rowSize = ((bw * bpx +
3
) /
4
) *
4
;
// rows padded to 4 bytes
w = bw; h = bh;
ArrayResize
(px, bw * bh);
for
(
int
y =
0
; y < bh; y++)
     {
int
srcRow  = topDown ? y : (bh -
1
- y);
// BMP is bottom-up by default
int
rowBase = dataOff + srcRow * rowSize;
int
dstBase = y * bw;
for
(
int
x =
0
; x < bw; x++)
        {
int
p = rowBase + x * bpx;
if
(p +
2
>= sz) { px[dstBase + x] =
0xFF000000
;
continue
; }
uint
bl = b[p], gr = b[p+
1
], re = b[p+
2
];
         px[dstBase + x] =
0xFF000000
| (re <<
16
) | (gr <<
8
) | bl;
        }
     }
return
true
;
  }
In the "Ai_DecodeBMP" function, we read the whole BMP file, check its header, and pull the width, height, and bit depth, leaning on the small "Ai_LE32" helper to read each little-endian field. We then walk the rows, flipping bottom-up files right-side up and reordering each pixel from the BMP's blue-green-red bytes into the top-down ARGB the canvas expects. With raw pixels in hand, we cache them at a light size so drawing a thumbnail stays cheap.
Caching the Thumbnail
Rather than decoding on every frame, we keep a small least-recently-used cache of downscaled thumbnails, one slot per image.
struct
AiImgThumb
  {
string
key;
// marker base name
uint
px[];
// ARGB pixels, top-down (w*h)
int
w;
int
h;
uint
used;
// last-access tick (LRU)
bool
valid;
  };
AiImgThumb g_ai_imgCache[AI_IMG_CACHE_MAX];
int
Ai_GetImageThumb(
string
base)
  {
//--- Already cached?
for
(
int
i =
0
; i < AI_IMG_CACHE_MAX; i++)
if
(g_ai_imgCache[i].valid && g_ai_imgCache[i].key == base)
        { g_ai_imgCache[i].used =
GetTickCount
();
return
i; }
//--- Decode from disk
uint
px[];
int
w =
0
, h =
0
;
if
(!Ai_DecodeBMP(AI_IMG_DIR + base +
".bmp"
, px, w, h))
return
-
1
;
//--- Downscale the native BMP to a light thumbnail for cheap inline caching
const
int
cap =
640
;
if
(w > cap || h > cap)
     {
double
s =
MathMin
((
double
)cap / (
double
)w, (
double
)cap / (
double
)h);
int
nw = (
int
)
MathRound
(w * s);
int
nh = (
int
)
MathRound
(h * s);
if
(nw <
1
) nw =
1
;
if
(nh <
1
) nh =
1
;
uint
sp[];
ArrayResize
(sp, nw * nh);
for
(
int
y =
0
; y < nh; y++)
        {
int
sy = (
int
)((
double
)y * (
double
)h / (
double
)nh);
if
(sy >= h) sy = h -
1
;
int
srow = sy * w, drow = y * nw;
for
(
int
x =
0
; x < nw; x++)
           {
int
sx = (
int
)((
double
)x * (
double
)w / (
double
)nw);
if
(sx >= w) sx = w -
1
;
            sp[drow + x] = px[srow + sx];
           }
        }
ArrayResize
(px, nw * nh);
ArrayCopy
(px, sp);
      w = nw; h = nh;
     }
//--- Pick a slot: first invalid, else least-recently-used
int
slot = -
1
;
uint
oldest =
UINT_MAX
;
for
(
int
i =
0
; i < AI_IMG_CACHE_MAX; i++)
     {
if
(!g_ai_imgCache[i].valid) { slot = i;
break
; }
if
(g_ai_imgCache[i].used < oldest) { oldest = g_ai_imgCache[i].used; slot = i; }
     }
   g_ai_imgCache[slot].key = base;
ArrayResize
(g_ai_imgCache[slot].px,
ArraySize
(px));
ArrayCopy
(g_ai_imgCache[slot].px, px);
   g_ai_imgCache[slot].w = w;
   g_ai_imgCache[slot].h = h;
   g_ai_imgCache[slot].used  =
GetTickCount
();
   g_ai_imgCache[slot].valid =
true
;
return
slot;
  }
We define the "AiImgThumb"
structure
to hold one cached thumbnail and, in the "Ai_GetImageThumb" function, first look for the image already in a slot before touching the disk. On a miss, we decode it, downscale anything larger than a 640-pixel cap so the cached copy stays light, and store it in a free slot or the least-recently-used one when the cache is full. A bounded pixel cache lets the chat render thumbnails without decoding on every scroll. Next, we draw the thumbnail and store its on-screen rectangle for click handling.
Drawing and Registering the Thumbnail
Painting a thumbnail into the chat means scaling the cached pixels into place and recording the on-screen rectangle so a click can later open it.
//--- On-screen thumbnail rects for this frame, rebuilt each chat render for hit-testing
string
g_ai_imgClickBase[];
int
g_ai_imgClickL[];
